param([Parameter(Mandatory=$true)][string]$OutputDirectory)$ErrorActionPreference='Stop';New-Item -ItemType Directory -Path $OutputDirectory -Force|Out-Null;$out=Join-Path $OutputDirectory ("tupiniquim-editorial-production-"+(Get-Date -Format 'yyyy-MM-dd-HHmmss')+".sql");npx wrangler d1 export tupiniquim-cms-drafts --remote --output $out;if(!(Test-Path $out)-or(Get-Item $out).Length-le 0){throw 'Backup ausente ou vazio.'};Get-FileHash $out -Algorithm SHA256|Format-List;Write-Host $out
